213→/* ===========================================
214→   ENTRANCE ANIMATIONS
215→   =========================================== */
216→
217→@keyframes fadeUp {
218→  from {
219→    opacity: 0;
220→    transform: translateY(21px);  /* Fibonacci */
221→  }
222→  to {
223→    opacity: 1;
224→    transform: translateY(0);
225→  }
226→}
227→
228→.project-card {
229→  opacity: 0;
230→  animation: fadeUp 0.7s ease-out forwards;
231→}
232→
233→.project-card:nth-child(1) { animation-delay: 0ms; }
234→.project-card:nth-child(2) { animation-delay: 80ms; }
235→.project-card:nth-child(3) { animation-delay: 160ms; }
236→.project-card:nth-child(4) { animation-delay: 240ms; }
237→.project-card:nth-child(5) { animation-delay: 320ms; }
238→.project-card:nth-child(6) { animation-delay: 400ms; }
239→
240→@keyframes fadeIn {
241→  from { opacity: 0; }
242→  to { opacity: 1; }
243→}
244→
245→.client-strip {
246→  animation: fadeIn 0.8s ease-out forwards;
247→  animation-delay: 200ms;
248→  opacity: 0;
249→}
250→
251→/* Scroll indicator */
252→@keyframes scrollFloat {
253→  0%, 100% {
254→    transform: translateY(0);
255→    opacity: 0.5;
256→  }
257→  50% {
258→    transform: translateY(6px);
259→    opacity: 0.8;
260→  }
261→}
262→
263→.scroll-chevron {
264→  animation: scrollFloat 2.8s ease-in-out infinite;
265→  will-change: transform, opacity;
266→}
267→
268→/* Chat typing indicator */
269→@keyframes typingPulse {
270→  0%, 100% {
271→    opacity: 0.3;
272→    transform: scale(1);
273→  }
274→  50% {
275→    opacity: 1;
276→    transform: scale(1.15);
277→  }
278→}
279→
280→.typing-dot {
281→  will-change: transform, opacity;
282→}
283→
284→/* Chat message entrance */
285→@keyframes chatMessageIn {
286→  from {
287→    opacity: 0;
288→    transform: translateY(13px);  /* --space-small: 21 / phi */
289→  }
290→  to {
291→    opacity: 1;
292→    transform: translateY(0);
293→  }
294→}
295→
296→.chat-message-enter {
297→  animation: chatMessageIn 0.3s ease-out forwards;
298→}
299→
300→/* Reduced motion */
301→@media (prefers-reduced-motion: reduce) {
302→  html {
303→    scroll-behavior: auto;
304→  }
305→
306→  *,
307→  *::before,
308→  *::after {
309→    animation-duration: 0.01ms !important;
310→    animation-iteration-count: 1 !important;
311→    transition-duration: 0.01ms !important;
312→  }
313→
314→  [aria-live="polite"] {
315→    transition: none !important;
316→  }
317→
318→  .nav-link,
319→  .project-title h3,
320→  .section-header-highlight,
321→  .project-card,
322→  .nav-item-shift,
323→  .button-arrow,
324→  .scroll-chevron,
325→  .typing-dot,
326→  .chat-message-enter {
327→    transition: none !important;
328→    transform: none !important;
329→    animation: none !important;
330→  }
331→}
